"use client";

import React, { useState, useMemo, useRef } from "react";
import {
    FileText, UploadCloud, Download, Trash2, Eye,
    Search, Clock, CheckCircle2, AlertCircle, Plus,
    X, Info, History, ShieldCheck, FileSearch
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";
import PageBreadcrumb from "@/components/common/PageBreadCrumb";

/* ========================
   TYPES & MOCK DATA
======================== */
type DocStatus = "Verified" | "Pending" | "Rejected" | "Expiring Soon";

interface DocumentItem {
    id: string;
    name: string;
    category: "Identity" | "Education" | "Company" | "Tax";
    size: string;
    uploadDate: string;
    status: DocStatus;
    expiryDate?: string;
    version: string;
}

const initialDocs: DocumentItem[] = [
    { id: "1", name: "Aadhar_Card.pdf", category: "Identity", size: "1.2 MB", uploadDate: "12 Jan 2026", status: "Verified", version: "v1.0" },
    { id: "2", name: "Degree_Certificate.pdf", category: "Education", size: "2.4 MB", uploadDate: "10 Jan 2026", status: "Verified", version: "v2.1" },
    { id: "3", name: "Passport_Copy.pdf", category: "Identity", size: "3.1 MB", uploadDate: "05 Jan 2026", status: "Expiring Soon", expiryDate: "20 Mar 2026", version: "v1.0" },
    { id: "4", name: "Offer_Letter.pdf", category: "Company", size: "850 KB", uploadDate: "01 Jan 2026", status: "Verified", version: "v1.1" },
];

export default function EmployeeDocumentHub() {
    // --- STATE MANAGEMENT ---
    const [docs, setDocs] = useState<DocumentItem[]>(initialDocs);
    const [search, setSearch] = useState("");
    const [activeTab, setActiveTab] = useState<string>("All");
    
    // UI States
    const [previewDoc, setPreviewDoc] = useState<DocumentItem | null>(null);
    const [showUpload, setShowUpload] = useState(false);
    const [showAudit, setShowAudit] = useState<DocumentItem | null>(null);

    // --- LOGIC: FILTERING ---
    const filteredDocs = useMemo(() => {
        return docs.filter(doc => {
            const matchesSearch = doc.name.toLowerCase().includes(search.toLowerCase());
            const matchesTab = activeTab === "All" || doc.category === activeTab;
            return matchesSearch && matchesTab;
        });
    }, [search, activeTab, docs]);

    // --- LOGIC: DELETE ---
    const handleDelete = (id: string) => {
        if(window.confirm("Move this document to trash?")) {
            setDocs(docs.filter(d => d.id !== id));
        }
    };

    // --- LOGIC: UPLOAD SIMULATION ---
    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const newDoc: DocumentItem = {
                id: Math.random().toString(),
                name: file.name,
                category: activeTab === "All" ? "Identity" : activeTab as any,
                size: (file.size / 1024 / 1024).toFixed(2) + " MB",
                uploadDate: "Just Now",
                status: "Pending",
                version: "v1.0"
            };
            setDocs([newDoc, ...docs]);
            setShowUpload(false);
        }
    };

    return (
        <div className="p-6 space-y-6 bg-[#F8F9FB] dark:bg-[#0B1120] min-h-screen relative">
            <PageBreadcrumb pageTitle="Document Hub" />

            {/* 1. STATS HUD */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <DocStatCard icon={<FileText />} label="Total Files" value={docs.length.toString()} color="brand" />
                <DocStatCard icon={<CheckCircle2 />} label="Verified" value="3" color="emerald" />
                <DocStatCard icon={<Clock />} label="Pending" value="1" color="amber" />
                <DocStatCard icon={<AlertCircle />} label="Action Required" value="1" color="red" />
            </div>

            {/* 2. ACTIONS & TABS BAR */}
            <div className="bg-white dark:bg-gray-900 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-800 flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="flex gap-2 overflow-x-auto pb-2 md:pb-0 no-scrollbar">
                    {["All", "Identity", "Education", "Company", "Tax"].map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab)}
                            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                                activeTab === tab 
                                ? "bg-brand-500 text-white shadow-md shadow-brand-500/20" 
                                : "text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800"
                            }`}
                        >
                            {tab}
                        </button>
                    ))}
                </div>

                <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute left-3 top-2.5 text-gray-400" size={16} />
                        <input
                            placeholder="Find a document..."
                            className="pl-9 w-full border-none bg-gray-50 dark:bg-gray-800 rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-brand-500 transition-all"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>
                    <button 
                        onClick={() => setShowUpload(true)}
                        className="bg-brand-500 hover:bg-brand-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 text-sm font-bold shadow-lg shadow-brand-500/20 transition-all"
                    >
                        <Plus size={18} /> Upload
                    </button>
                </div>
            </div>

            {/* 3. THE MAIN DATA TABLE (The View You Liked) */}
            <div className="bg-white dark:bg-gray-900 rounded-[2rem] shadow-sm border border-gray-100 dark:border-gray-800 overflow-hidden">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50/50 dark:bg-gray-800/50 text-[11px] uppercase tracking-widest text-gray-400">
                            <th className="px-6 py-4 font-black">Document Name</th>
                            <th className="px-6 py-4 font-black">Category</th>
                            <th className="px-6 py-4 font-black text-center">Version</th>
                            <th className="px-6 py-4 font-black">Status</th>
                            <th className="px-6 py-4 font-black text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
                        {filteredDocs.map((doc) => (
                            <tr key={doc.id} className="group hover:bg-gray-50/50 dark:hover:bg-gray-800/50 transition-colors">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 bg-brand-50 dark:bg-brand-500/10 rounded-xl flex items-center justify-center text-brand-600">
                                            <FileText size={20} />
                                        </div>
                                        <div>
                                            <p className="text-sm font-bold text-gray-900 dark:text-white">{doc.name}</p>
                                            <p className="text-[10px] text-gray-400 font-bold uppercase">{doc.size} • {doc.uploadDate}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4"><span className="text-xs font-medium text-gray-500">{doc.category}</span></td>
                                <td className="px-6 py-4 text-center"><span className="text-[10px] font-mono bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded">{doc.version}</span></td>
                                <td className="px-6 py-4">
                                    <StatusBadge status={doc.status} />
                                    {doc.expiryDate && <p className="text-[9px] text-red-500 font-bold mt-1">Expires: {doc.expiryDate}</p>}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => setPreviewDoc(doc)} className="p-2 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-lg transition-all"><Eye size={18}/></button>
                                        <button onClick={() => setShowAudit(doc)} className="p-2 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-lg transition-all"><History size={18}/></button>
                                        <button className="p-2 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-lg transition-all"><Download size={18}/></button>
                                        <button onClick={() => handleDelete(doc.id)} className="p-2 text-gray-400 hover:text-red-500 hover:bg-white dark:hover:bg-gray-800 rounded-lg transition-all"><Trash2 size={18}/></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* --- FUNCTIONALITY OVERLAYS --- */}

            {/* A. UPLOAD MODAL (Simplified Drawer) */}
            {showUpload && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowUpload(false)} />
                    <div className="relative bg-white dark:bg-gray-900 rounded-[2.5rem] p-8 w-full max-w-md shadow-2xl animate-in zoom-in-95 duration-200">
                        <h3 className="text-xl font-black mb-6">Upload Document</h3>
                        <label className="border-4 border-dashed border-gray-100 dark:border-gray-800 rounded-[2rem] p-10 flex flex-col items-center justify-center cursor-pointer hover:border-brand-500 transition-colors">
                            <UploadCloud size={40} className="text-gray-300 mb-2" />
                            <span className="text-xs font-bold text-gray-500 uppercase">Click to browse files</span>
                            <input type="file" className="hidden" onChange={handleFileUpload} />
                        </label>
                        <button onClick={() => setShowUpload(false)} className="mt-4 w-full py-3 text-sm font-bold text-gray-400">Cancel</button>
                    </div>
                </div>
            )}

            {/* B. DOCUMENT PREVIEW (Glassmorphism Overlay) */}
            {previewDoc && (
                <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-xl p-6 flex flex-col items-center animate-in fade-in duration-300">
                    <div className="w-full max-w-5xl flex justify-between items-center mb-6">
                        <h2 className="text-white font-black text-xl">{previewDoc.name}</h2>
                        <button onClick={() => setPreviewDoc(null)} className="p-3 bg-white/10 text-white rounded-full hover:bg-white/20"><X size={24} /></button>
                    </div>
                    <div className="flex-1 w-full max-w-5xl bg-white rounded-[2rem] flex flex-col items-center justify-center overflow-hidden">
                        <FileSearch size={64} className="text-gray-200 mb-4" />
                        <p className="text-gray-400 font-bold uppercase tracking-widest">Generating Encrypted Preview...</p>
                        {/* <iframe> would go here for real PDF viewing */}
                    </div>
                </div>
            )}

            {/* C. AUDIT TRAIL SIDEBAR (Functional Context) */}
            {showAudit && (
                <div className="fixed top-0 right-0 w-80 h-full bg-white dark:bg-gray-900 shadow-2xl z-[150] p-8 border-l dark:border-gray-800 animate-in slide-in-from-right duration-300">
                    <div className="flex items-center justify-between mb-8">
                        <h3 className="font-black uppercase text-xs tracking-widest text-gray-400">Audit Trail</h3>
                        <button onClick={() => setShowAudit(null)}><X size={20}/></button>
                    </div>
                    <div className="space-y-6">
                        <AuditItem title="Document Uploaded" time="12 Jan, 10:20 AM" user="You" />
                        <AuditItem title="OCR Verification" time="12 Jan, 10:21 AM" user="System" />
                        <AuditItem title="Viewed by HR" time="13 Jan, 09:15 AM" user="Admin_1" />
                    </div>
                </div>
            )}
        </div>
    );
}

/* --- REUSABLE PIECES --- */

const DocStatCard = ({ icon, label, value, color }: any) => (
    <div className="bg-white dark:bg-gray-900 p-6 rounded-[2rem] border border-gray-100 dark:border-gray-800 shadow-sm transition-transform hover:scale-105 cursor-default">
        <div className={`w-10 h-10 rounded-xl bg-${color}-50 dark:bg-${color}-500/10 flex items-center justify-center text-${color}-600 mb-4`}>
            {icon}
        </div>
        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{label}</p>
        <h3 className="text-2xl font-black text-gray-900 dark:text-white mt-1">{value}</h3>
    </div>
);

const AuditItem = ({ title, time, user }: any) => (
    <div className="relative pl-6 border-l-2 border-gray-100 dark:border-gray-800">
        <div className="absolute top-0 -left-[7px] w-3 h-3 rounded-full bg-brand-500" />
        <p className="text-sm font-bold text-gray-900 dark:text-white leading-none mb-1">{title}</p>
        <p className="text-[10px] text-gray-400 font-medium">{time} • {user}</p>
    </div>
);

const StatusBadge = ({ status }: { status: DocStatus }) => {
    const variants: any = {
        Verified: { color: "success" },
        Pending: { color: "warning" },
        Rejected: { color: "error" },
        "Expiring Soon": { color: "warning" },
    };
    return <Badge size="sm" color={variants[status].color as any}>{status}</Badge>;
};